/**
 * Atelier's business schema, written once for PostgreSQL and SQLite.
 *
 * PostgreSQL is the target: numeric money, real dates and timestamps, bytea
 * photos, identity keys. SQLite gets the same tables, names and CHECKs with
 * its own spellings of those types, so the sample tests and a quick local
 * try run on a file. `ddl(dialect)` returns the statements in foreign-key
 * order.
 *
 * Money is decimal for now, every money column named `…_amount` (and
 * `tax_rate` a fraction), so moving to integer minor units is one rename and
 * one type per column. The totals CHECKs compare within half a cent: exact on
 * PostgreSQL's numeric, and tolerant of SQLite's REAL arithmetic.
 */

const DIALECTS = {
  postgres: {
    id: 'id integer generated by default as identity primary key',
    money: 'numeric(12,2)',
    rate: 'numeric(6,5)',
    percent: 'numeric(5,2)',
    date: 'date',
    ts: 'timestamp',
    bytes: 'bytea',
    yes: 'true',
    no: 'false',
  },
  sqlite: {
    id: 'id INTEGER PRIMARY KEY',
    money: 'NUMERIC(12,2)',
    rate: 'NUMERIC(6,5)',
    percent: 'NUMERIC(5,2)',
    date: 'DATE',
    ts: 'TIMESTAMP',
    bytes: 'BLOB',
    yes: '1',
    no: '0',
  },
};

/** The tables in foreign-key order, as [name, statement]. */
export function ddl(dialect) {
  const d = DIALECTS[dialect];
  if (!d) throw new Error(`Unknown dialect ${dialect}`);
  const { id, money, rate, percent, date, ts, bytes, yes, no } = d;
  const version = 'version integer NOT NULL DEFAULT 0';
  return [
    [
      'location',
      `CREATE TABLE location (${id}, code text NOT NULL UNIQUE, name text NOT NULL,
        kind text NOT NULL CHECK (kind IN ('store', 'warehouse')), address text NOT NULL, city text NOT NULL,
        state text NOT NULL, ships_online boolean NOT NULL DEFAULT ${no}, active boolean NOT NULL DEFAULT ${yes})`,
    ],
    [
      'tag',
      `CREATE TABLE tag (${id}, name text NOT NULL UNIQUE,
        tone text NOT NULL DEFAULT 'neutral' CHECK (tone IN ('good', 'warn', 'bad', 'info', 'neutral')))`,
    ],
    [
      'product',
      `CREATE TABLE product (${id}, title text NOT NULL, handle text NOT NULL UNIQUE, vendor text NOT NULL,
        product_type text NOT NULL, category text NOT NULL CHECK (category IN ('apparel', 'shoes', 'accessories')),
        status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'archived')),
        description text, material text, care text, created_on ${date} NOT NULL DEFAULT CURRENT_DATE, ${version})`,
    ],
    [
      'product_tag',
      `CREATE TABLE product_tag (${id}, product_id integer NOT NULL REFERENCES product(id),
        tag_id integer NOT NULL REFERENCES tag(id), UNIQUE (product_id, tag_id))`,
    ],
    [
      'product_image',
      `CREATE TABLE product_image (${id}, product_id integer NOT NULL REFERENCES product(id), position integer NOT NULL,
        alt text, file_name text NOT NULL, content_type text, byte_size integer, data ${bytes} NOT NULL, thumbnail ${bytes})`,
    ],
    [
      'collection',
      `CREATE TABLE collection (${id}, title text NOT NULL UNIQUE, handle text NOT NULL UNIQUE, description text,
        published boolean NOT NULL DEFAULT ${yes}, created_on ${date} NOT NULL DEFAULT CURRENT_DATE, ${version})`,
    ],
    [
      'collection_product',
      `CREATE TABLE collection_product (${id}, collection_id integer NOT NULL REFERENCES collection(id),
        product_id integer NOT NULL REFERENCES product(id), position integer NOT NULL DEFAULT 0,
        UNIQUE (collection_id, product_id))`,
    ],
    [
      'variant',
      `CREATE TABLE variant (${id}, product_id integer NOT NULL REFERENCES product(id), sku text NOT NULL UNIQUE,
        color text NOT NULL, size text NOT NULL, position integer NOT NULL DEFAULT 0,
        price_amount ${money} NOT NULL CHECK (price_amount > 0),
        compare_at_amount ${money} CHECK (compare_at_amount IS NULL OR compare_at_amount > price_amount),
        cost_amount ${money} NOT NULL CHECK (cost_amount >= 0), barcode text UNIQUE,
        reorder_point integer NOT NULL DEFAULT 3 CHECK (reorder_point >= 0),
        active boolean NOT NULL DEFAULT ${yes}, ${version}, UNIQUE (product_id, color, size))`,
    ],
    [
      // One row per variant and location. on_hand never goes below zero: the commands refuse first, this is the last word.
      'inventory_level',
      `CREATE TABLE inventory_level (${id}, variant_id integer NOT NULL REFERENCES variant(id),
        location_id integer NOT NULL REFERENCES location(id), on_hand integer NOT NULL DEFAULT 0 CHECK (on_hand >= 0),
        ${version}, UNIQUE (variant_id, location_id))`,
    ],
    [
      'customer',
      `CREATE TABLE customer (${id}, name text NOT NULL, email text NOT NULL UNIQUE, phone text,
        address text, city text NOT NULL, state text NOT NULL, zip text, accepts_marketing boolean NOT NULL DEFAULT ${no},
        created_on ${date} NOT NULL DEFAULT CURRENT_DATE, note text, ${version})`,
    ],
    [
      'discount',
      `CREATE TABLE discount (${id}, code text NOT NULL UNIQUE CHECK (code = upper(code)), description text NOT NULL,
        kind text NOT NULL CHECK (kind IN ('percent', 'fixed')),
        percent_off ${percent}, amount_off_amount ${money},
        min_subtotal_amount ${money} NOT NULL DEFAULT 0 CHECK (min_subtotal_amount >= 0),
        starts_on ${date} NOT NULL, ends_on ${date}, usage_limit integer CHECK (usage_limit IS NULL OR usage_limit > 0),
        active boolean NOT NULL DEFAULT ${yes}, ${version},
        CHECK ((kind = 'percent' AND percent_off > 0 AND percent_off <= 90 AND amount_off_amount IS NULL)
            OR (kind = 'fixed' AND amount_off_amount > 0 AND percent_off IS NULL)),
        CHECK (ends_on IS NULL OR ends_on >= starts_on))`,
    ],
    [
      /* An order. Where its payment and its fulfillment stand is theirs to say (each its own record, with its own
         machine), read on the order as rollups. total = subtotal − discount + shipping + tax. */
      'sales_order',
      `CREATE TABLE sales_order (${id}, customer_id integer NOT NULL REFERENCES customer(id),
        location_id integer NOT NULL REFERENCES location(id),
        channel text NOT NULL CHECK (channel IN ('online', 'store', 'phone')), placed_at ${ts} NOT NULL,
        status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'confirmed', 'completed', 'cancelled')),
        shipping_method text NOT NULL CHECK (shipping_method IN ('standard', 'express', 'pickup')),
        ship_name text NOT NULL, ship_address text, ship_city text NOT NULL, ship_state text NOT NULL, ship_zip text,
        discount_id integer REFERENCES discount(id), discount_code text,
        subtotal_amount ${money} NOT NULL CHECK (subtotal_amount >= 0),
        discount_amount ${money} NOT NULL DEFAULT 0 CHECK (discount_amount >= 0 AND discount_amount <= subtotal_amount),
        shipping_amount ${money} NOT NULL DEFAULT 0 CHECK (shipping_amount >= 0),
        tax_rate ${rate} NOT NULL DEFAULT 0 CHECK (tax_rate >= 0 AND tax_rate < 0.2),
        tax_amount ${money} NOT NULL DEFAULT 0 CHECK (tax_amount >= 0),
        total_amount ${money} NOT NULL CHECK (total_amount >= 0),
        note text, confirmed_at ${ts}, completed_at ${ts}, cancelled_at ${ts}, cancel_reason text, ${version},
        CHECK (abs(total_amount - (subtotal_amount - discount_amount + shipping_amount + tax_amount)) < 0.005),
        CHECK ((status = 'cancelled') = (cancelled_at IS NOT NULL)))`,
    ],
    [
      'order_line',
      `CREATE TABLE order_line (${id}, sales_order_id integer NOT NULL REFERENCES sales_order(id),
        line_no integer NOT NULL CHECK (line_no > 0), variant_id integer NOT NULL REFERENCES variant(id),
        sku text NOT NULL, description text NOT NULL,
        quantity integer NOT NULL CHECK (quantity > 0), unit_price_amount ${money} NOT NULL CHECK (unit_price_amount >= 0),
        line_amount ${money} NOT NULL, UNIQUE (sales_order_id, line_no),
        CHECK (abs(line_amount - quantity * unit_price_amount) < 0.005))`,
    ],
    [
      // What the order is paid with. A refund only records money given back; refunded never exceeds paid.
      'payment',
      `CREATE TABLE payment (${id}, sales_order_id integer NOT NULL UNIQUE REFERENCES sales_order(id),
        method text NOT NULL CHECK (method IN ('card', 'paypal', 'apple_pay', 'cash', 'gift_card')),
        status text NOT NULL DEFAULT 'pending'
          CHECK (status IN ('pending', 'paid', 'partially_refunded', 'refunded', 'voided')),
        charge_amount ${money} NOT NULL CHECK (charge_amount >= 0),
        paid_amount ${money} NOT NULL DEFAULT 0 CHECK (paid_amount >= 0 AND paid_amount <= charge_amount),
        refunded_amount ${money} NOT NULL DEFAULT 0 CHECK (refunded_amount >= 0 AND refunded_amount <= paid_amount),
        reference text, paid_at ${ts}, ${version},
        CHECK ((status = 'pending' OR status = 'voided') = (paid_at IS NULL)))`,
    ],
    [
      'fulfillment',
      `CREATE TABLE fulfillment (${id}, sales_order_id integer NOT NULL UNIQUE REFERENCES sales_order(id),
        location_id integer NOT NULL REFERENCES location(id),
        status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'packed', 'shipped', 'delivered', 'cancelled')),
        carrier text CHECK (carrier IS NULL OR carrier IN ('UPS', 'USPS', 'FedEx', 'DHL', 'Pickup')),
        tracking_number text, packed_at ${ts}, packed_by text, shipped_at ${ts}, delivered_at ${ts}, ${version},
        CHECK (status IN ('pending', 'cancelled') OR packed_at IS NOT NULL),
        CHECK (status NOT IN ('shipped', 'delivered') OR (shipped_at IS NOT NULL AND carrier IS NOT NULL)))`,
    ],
    [
      'order_return',
      `CREATE TABLE order_return (${id}, sales_order_id integer NOT NULL REFERENCES sales_order(id),
        status text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested', 'approved', 'received', 'refunded', 'rejected')),
        reason text NOT NULL CHECK (reason IN ('too_small', 'too_large', 'not_as_pictured', 'changed_mind', 'damaged', 'arrived_late')),
        requested_on ${date} NOT NULL, location_id integer REFERENCES location(id), received_at ${ts},
        refund_amount ${money} CHECK (refund_amount IS NULL OR refund_amount > 0), note text, ${version})`,
    ],
    [
      'return_line',
      `CREATE TABLE return_line (${id}, order_return_id integer NOT NULL REFERENCES order_return(id),
        order_line_id integer NOT NULL REFERENCES order_line(id),
        quantity integer NOT NULL CHECK (quantity > 0), restock boolean NOT NULL DEFAULT ${yes},
        UNIQUE (order_return_id, order_line_id))`,
    ],
    [
      'refund',
      `CREATE TABLE refund (${id}, payment_id integer NOT NULL REFERENCES payment(id),
        sales_order_id integer NOT NULL REFERENCES sales_order(id), order_return_id integer REFERENCES order_return(id),
        refund_amount ${money} NOT NULL CHECK (refund_amount > 0), reason text NOT NULL, refunded_at ${ts} NOT NULL,
        refunded_by text)`,
    ],
    [
      // The stock ledger: every unit in and out of a location, with the location's count after it.
      'inventory_movement',
      `CREATE TABLE inventory_movement (${id}, moved_at ${ts} NOT NULL,
        kind text NOT NULL CHECK (kind IN ('received', 'fulfilled', 'returned', 'adjusted')),
        variant_id integer NOT NULL REFERENCES variant(id), location_id integer NOT NULL REFERENCES location(id),
        quantity integer NOT NULL CHECK (quantity <> 0), on_hand_after integer NOT NULL CHECK (on_hand_after >= 0),
        reference text NOT NULL, reason text, moved_by text,
        fulfillment_id integer REFERENCES fulfillment(id), order_return_id integer REFERENCES order_return(id))`,
    ],
  ];
}

/** Indexes the lists and the commands lean on. */
export const INDEXES = [
  'CREATE INDEX order_by_customer ON sales_order(customer_id)',
  'CREATE INDEX order_by_placed ON sales_order(placed_at)',
  'CREATE INDEX line_by_order ON order_line(sales_order_id)',
  'CREATE INDEX line_by_variant ON order_line(variant_id)',
  'CREATE INDEX variant_by_product ON variant(product_id)',
  'CREATE INDEX level_by_location ON inventory_level(location_id)',
  'CREATE INDEX movement_by_variant ON inventory_movement(variant_id)',
  'CREATE INDEX movement_by_moved ON inventory_movement(moved_at)',
  'CREATE INDEX image_by_product ON product_image(product_id)',
  'CREATE INDEX return_by_order ON order_return(sales_order_id)',
  'CREATE INDEX return_line_by_return ON return_line(order_return_id)',
  'CREATE INDEX refund_by_payment ON refund(payment_id)',
  'CREATE INDEX refund_by_order ON refund(sales_order_id)',
  'CREATE INDEX order_by_discount ON sales_order(discount_id)',
  'CREATE INDEX movement_by_fulfillment ON inventory_movement(fulfillment_id)',
  'CREATE INDEX movement_by_return ON inventory_movement(order_return_id)',
  'CREATE INDEX collection_product_by_product ON collection_product(product_id)',
  'CREATE INDEX product_tag_by_tag ON product_tag(tag_id)',
];
